    caja: { t: 'Caja', s: 4, fn: wCaja },
    flujo: { t: 'Cobros esperados por mes', s: 6, fn: wFlujo },
    equipos: { t: 'Equipos que más dejan', s: 6, fn: wEquipos },
    actividad: { t: 'Actividad de referidores', s: 6, fn: wActividad },
