  function wStock() { const inv = A.db.inventory, units = inv.reduce((a, x) => a + Math.max(0, Number(x.stock) || 0), 0), low = inv.filter((x) => Number(x.stock) === 1), out = inv.filter((x) => !(Number(x.stock) > 0)); return wHead('Stock', '<a class="small" href="#inventario">Ver</a>') + '<div class="big-num">' + units + ' <span class="small muted">unidades</span></div>' + (low.length ? '<div class="small strong warn" style="margin-top:8px">Queda 1:</div>' + low.slice(0, 4).map((x) => '<div class="small">' + esc(x.name + (x.spec ? ' · ' + x.spec : '')) + '</div>').join('') : '') + (out.length ? '<div class="small strong bad" style="margin-top:8px">Sin stock (' + out.length + '):</div>' + out.slice(0, 4).map((x) => '<div class="small muted">' + esc(x.name + (x.spec ? ' · ' + x.spec : '')) + '</div>').join('') : ''); }
  function wInteresados() { const p = (A.db.pedidos || []).filter((x) => (x.estado || 'nueva') === 'nueva').slice().reverse(); return wHead('Interesados', '<a class="small" href="#estadisticas">Ver</a>') + (p.length ? '<div class="big-num">' + p.length + ' <span class="small muted">sin responder</span></div>' + p.slice(0, 4).map((x) => '<div class="sum-line"><span>' + esc(x.prod || 'Consulta') + '<br><span class="tiny muted">' + esc(((A.db.clients[x.phone] || {}).name || x.phone || '') + ' · ' + (x.f || '')) + '</span></span>' + (x.phone ? '<a class="btn btn-sm btn-wa" target="_blank" rel="noopener" href="' + A.waLink(x.phone, 'Hola, te escribimos de ICLUB por tu consulta sobre ' + (x.prod || 'el equipo') + '.') + '">WA</a>' : '') + '</div>').join('') : empty('Sin consultas nuevas.')); }
  function wClientes() { const all = Object.keys(A.db.clients).map((ph) => M.client(A.db, ph)); const mk = M.monthKey(new Date()); const nuevos = Object.values(A.db.clients).filter((c) => c.createdAt && M.monthKey(new Date(c.createdAt)) === mk).length; return wHead('Clientes', '<a class="small" href="#clientes">Ver</a>') + '<div class="big-num">' + all.length + '</div><div class="sum-line"><span>Con deuda</span><b>' + all.filter((x) => x.saldo > 0.005).length + '</b></div><div class="sum-line"><span>Atrasados</span><b class="bad">' + all.filter((x) => x.estado === 'atrasado').length + '</b></div><div class="sum-line" style="border:0"><span>Nuevos este mes</span><b>' + nuevos + '</b></div>'; }
  function wInversores() { if (!A.net) return wHead('Inversores') + empty('Falta instalar la actualización 11.'); const l = Object.entries(A.net.data.investors || {}).map(([ph, inv]) => ({ inv, x: M.investor(inv, (A.net.data.investorMoves || []).filter((m) => m.phone === ph)) })); const next = l.map((i) => i.x.proximo).filter(Boolean).sort((a, b) => a - b)[0]; return wHead('Inversores', '<a class="small" href="#inversores">Ver</a>') + '<div class="big-num">' + ars(l.reduce((a, i) => a + i.x.capital, 0)) + '</div><div class="small muted">capital invertido</div><div class="sum-line"><span>Pagás por mes</span><b>' + ars(l.reduce((a, i) => a + i.x.mensual, 0)) + '</b></div><div class="sum-line" style="border:0"><span>Pendiente de pagar</span><b class="bad">' + ars(l.reduce((a, i) => a + i.x.pendiente, 0)) + '</b></div>' + (next ? '<div class="small">Próximo pago: <b>' + M.fmtDate(next) + '</b></div>' : ''); }
  function wCaja() { const bal = B.cashBalances(A.db); return wHead('Caja', '<a class="small" href="#finanzas">Ver</a>') + (bal ? Object.entries(bal).map(([w, n]) => '<div class="sum-line"><span>' + esc(w) + '</span><b>' + A.money(n, w.slice(0, 3)) + '</b></div>').join('') : empty('Configurá el saldo inicial en Finanzas.')); }
  function wFlujo() { const f = M.finance(A.db, {}).flujo.filter((x) => x.esperado != null).slice(0, 6), mx = Math.max(1, ...f.map((x) => x.esperado)); return wHead('Cobros esperados', '<a class="small" href="#finanzas">Ver</a>') + '<div class="bars" style="height:150px">' + f.map((x) => '<div class="b"><span class="tiny strong">' + (x.esperado >= 1e6 ? (x.esperado / 1e6).toFixed(1) + 'M' : Math.round(x.esperado / 1000) + 'k') + '</span><div class="pair"><i class="exp" style="height:' + Math.round(x.esperado / mx * 100) + '%;width:60%"></i></div><span class="lbl">' + esc(x.label) + '</span></div>').join('') + '</div>'; }
  function wEquipos() { const e = M.finance(A.db, { allTime: true }).equipos.slice(0, 5), mx = Math.max(1, ...e.map((x) => Math.abs(x.ganancia))); return wHead('Equipos que más dejan', '<span class="tiny muted">histórico</span>') + (e.length ? e.map((x) => '<div class="hbar"><span class="name">' + esc(x.name) + ' <span class="tiny muted">×' + x.unidades + '</span></span><span class="track"><i style="width:' + Math.round(Math.abs(x.ganancia) / mx * 100) + '%"></i></span><span class="val">' + ars(x.ganancia) + '</span></div>').join('') : empty('Sin ventas.')); }
