  function wVisitas() { const st = (A.net && A.net.stats) || [], days = []; for (let i = 13; i >= 0; i--) days.push(M.iso(new Date(Date.now() - i * 864e5))); const v = days.map((d) => st.filter((s) => s.kind === 'view' && s.day === d).reduce((a, s) => a + s.n, 0)), mx = Math.max(1, ...v); return wHead('Visitas · 14 días', '<a class="small" href="#estadisticas">Ver</a>') + '<div class="big-num">' + v.reduce((a, b) => a + b, 0) + '</div><div class="bars" style="height:90px">' + v.map((n) => '<div class="b"><div class="pair"><i class="exp" style="height:' + Math.round(n / mx * 100) + '%;width:70%"></i></div></div>').join('') + '</div>'; }
