    const head1 = rows.shift(); rows.sort((a, b) => (M.parseDate(a[0]) - M.parseDate(b[0]))); rows.unshift(head1);
    const blob = new Blob(['﻿' + rows.map((r) => r.map(q).join(';')).join('\r\n')], { type: 'text/csv;charset=utf-8' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'ICLUB-movimientos-' + M.iso(from) + '-a-' + M.iso(to) + '.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1500); A.toast('CSV descargado: ' + (rows.length - 1) + ' movimientos.');
